  [440784] = {
    [1] = {
      beijing = 1671,
      dialog = 3,
      music = "04_Normal",
      renwu = "npc",
      sentence = "The weight of a fluffy orange cat was undeniable. Luckily, Auntie Chen called us to dinner at just the right moment, and I managed to escape the awkward situation.",
