      idx = 5,
      music = "04_Normal",
      renming = "Auntie Chen",
      renwu = "npc",
      sentence = "Chubby used to be so attached to me. He even slept in the same bed with me. But lately... I don't know. He's become so aggressive, and not clingy anymore.",
