      role1 = 409000,
      role2 = 403111,
      role3 = 403207,
      role5 = 409401,
      sentence = "The instant our eyes met, a smile crept across his lips, but it didn't reach his eyes, and his tone stayed polite, yet formal like mine.",
      next = {12}
    },
    [12] = {
