      renwu = "npc",
      role1 = 409000,
      role2 = 403111,
      role3 = 403207,
      role5 = 409401,
      sentence = "My name's Gavin. I've been overseas doing business for some time and only just returned to the States. Would you do me the honor, Miss $u?",
