    },
    [28] = {
      beijing = 3025,
      dialog = 3,
      music = "1017_2023christmas",
      renwu = "npc",
      sentence = "Over time, a notion started circulating among the old money—that these people were all classless nouveau riche who made their money from illegal ventures overseas.",
