      role1 = 409000,
      role2 = 403111,
      role3 = 403207,
      role5 = 409401,
      roleanim = 1.1,
      ruchang = -1,
      sentence = "As I pondered these things, I was suddenly dipped at the waist by Gavin and found myself staring right into his face. He was dashing and handsome, but with an almost imperceptible air of estrangement.",
