    [44] = {
      beijing = 3025,
      dialog = 3,
      music = "1017_2023christmas",
      renwu = "npc",
      sentence = "With the people I cared about all leaving me, and with society rapidly changing, it seemed the only good thing to do with all this wealth was to squander it away.",
