      role2 = 703102,
      role3 = 703201,
      ruchang = -1,
      sentence = "So, this is what I've been working on.",
      next = {4}
    },
    [4] = {
      beijing = 1221,
      dialog = 3,
      music = "60_Beaytiful_Daily",
      renwu = "npc",
      role1 = 725000,
      role2 = 703102,
      role3 = 703201,
      sentence = "On the podium, Shaw picked up a KT board with a jade snuff bottle on it.",
      next = {5}
    },
    [5] = {
      beijing = 1221,
      dialog = 3,
      music = "60_Beaytiful_Daily",
      renwu = "npc",
      role1 = 725000,
      role2 = 703101,
      role3 = 703201,
      sentence = "Some distance away, the camera crew suddenly emerged without a sound. Noticing them, Shaw cast me a glance from afar.",
      next = {6}
    },
    [6] = {
      beijing = 1221,
      dialog = 3,
      music = "60_Beaytiful_Daily",
      renwu = "npc",
      role1 = 725000,
      role2 = 703101,
      role3 = 703201,
      sentence = "I didn't tell him I had brought the camera crew with me because I wanted to give him a surprise.",
      next = {7}
    },
    [7] = {
      beijing = 1221,
      dialog = 3,
      music = "60_Beaytiful_Daily",
      renwu = "npc",
      role1 = 725000,
      role2 = 703102,
      role3 = 703201,
      sentence = "A few seconds later, Shaw raised his eyebrow and looked away without a trace.",
      next = {8}
    },
    [8] = {
      beijing = 1221,
      dialog = 2,
      idx = 8,
      music = "60_Beaytiful_Daily",
      renming = "Shaw",
      renwu = "npc",
      role1 = 725000,
      role2 = 703102,
      role3 = 703201,
      sentence = "The snuff bottle may be a bit of a strange sight, but it's a piece of art that combines multiple crafts.",
      next = {9}
    },
    [9] = {
      beijing = 1221,
      dialog = 2,
      idx = 8,
      music = "60_Beaytiful_Daily",
      renming = "Shaw",
      renwu = "npc",
      role1 = 725000,
      role2 = 703102,
      role3 = 703201,
      sentence = "Like this one in my hand. It's made of jade and covered with painstakingly carved patterns, which come in different grades.",
      next = {10}
    },
    [10] = {
      beijing = 1221,
      dialog = 2,
      idx = 8,
      music = "60_Beaytiful_Daily",
      renming = "Shaw",
      renwu = "npc",
      role1 = 725000,
      role2 = 703102,
      role3 = 703201,
      sentence = "And so, by the Qianlong reign, few people used it to smoke cigarettes anymore. Instead, it had become a status symbol reserved for princes and ministers alike.",
      next = {11}
    },
    [11] = {
      beijing = 1221,
      dialog = 2,
      idx = 8,
      music = "60_Beaytiful_Daily",
      renming = "Shaw",
      renwu = "npc",
      role1 = 725000,
      role2 = 703102,
      role3 = 703201,
      sentence = "After all, the ancients have been known to be keen on \"quietly flaunting their wealth.\"",
      next = {12}
    },
    [12] = {
      beijing = 1221,
      dialog = 3,
      music = "60_Beaytiful_Daily",
      renwu = "npc",
      role1 = 725000,
      role2 = 703102,
      role3 = 703201,
      sentence = "That immediately drew laughter from the audience. Meanwhile, a student in the back raised his hand.",
      next = {13}
    },
    [13] = {
      beijing = 1221,
      dialog = 2,
      idx = 5,
      music = "60_Beaytiful_Daily",
      renming = "Student",
      renwu = "npc",
      role1 = 725000,
      role2 = 703102,
      role3 = 703201,
      sentence = "As you just said, snuff bottles may look attractive, but hardly anyone uses them anymore.",
      next = {14}
    },
    [14] = {
      beijing = 1221,
      dialog = 2,
      idx = 5,
      music = "60_Beaytiful_Daily",
      renming = "Student",
      renwu = "npc",
      role1 = 725000,
      role2 = 703102,
      role3 = 703201,
      sentence = "Being a pragmatist, I'm curious, why study something that has lost its utility?",
      next = {15}
    },
    [15] = {
      beijing = 1221,
      dialog = 3,
      music = "60_Beaytiful_Daily",
      renwu = "npc",
      role1 = 725000,
      role2 = 703102,
      role3 = 703201,
      sentence = "I thought Shaw would have frowned in displeasure at the somewhat sharp question, but instead, he let out a soft chuckle.",
      next = {16}
    },
    [16] = {
      beijing = 1221,
      dialog = 2,
      idx = 8,
      music = "60_Beaytiful_Daily",
      renming = "Shaw",
      renwu = "npc",
      role1 = 725000,
      role2 = 703102,
      role3 = 703201,
      sentence = "Good question.",
      next = {17}
    },
    [17] = {
      beijing = 1221,
      dialog = 2,
      idx = 8,
      music = "60_Beaytiful_Daily",
      renming = "Shaw",
      renwu = "npc",
      role1 = 725000,
      role2 = 703102,
      role3 = 703201,
      sentence = "Utility-wise, it has lost its value, yes.",
      next = {18}
    },
    [18] = {
      beijing = 1221,
      dialog = 2,
      idx = 8,
      music = "60_Beaytiful_Daily",
      renming = "Shaw",
      renwu = "npc",
      role1 = 725000,
      role2 = 703102,
      role3 = 703201,
      sentence = "But who says utility is the only measure of value?",
      next = {19}
    },
    [19] = {
      beijing = 1221,
      dialog = 3,
      music = "60_Beaytiful_Daily",
      renwu = "npc",
      role1 = 725000,
      role2 = 703102,
      role3 = 703201,
      sentence = "In the bright light, he looked as dazzling as the blue and purple hair he sported.",
      next = {20}
    },
    [20] = {
      beijing = 1221,
      dialog = 2,
      idx = 8,
      music = "60_Beaytiful_Daily",
      renming = "Shaw",
      renwu = "npc",
      role1 = 725000,
      role2 = 703102,
      role3 = 703202,
      sentence = "I'll spare you the cliche about \"preserving traditions and learning from history.\" Instead, I'm going to tell you something different.",
      next = {21}
    },
    [21] = {
      beijing = 1221,
      dialog = 2,
      idx = 8,
      music = "60_Beaytiful_Daily",
      renming = "Shaw",
      renwu = "npc",
      role1 = 725000,
      role2 = 703102,
      role3 = 703202,
      sentence = "Snuff was an imported product. First brought to China from Europe in the early Qing Dynasty.",
      next = {22}
    },
    [22] = {
      beijing = 1221,
      dialog = 2,
      idx = 8,
      music = "60_Beaytiful_Daily",
      renming = "Shaw",
      renwu = "npc",
      role1 = 725000,
      role2 = 703102,
      role3 = 703202,
      sentence = "The original brass cigarette case and glass bottle were neither aesthetic nor practical. So after being brought to China, they were gradually modified into the small, exquisite Chinese snuff bottle.",
      next = {23}
    },
    [23] = {
      beijing = 1221,
      dialog = 2,
      idx = 8,
      music = "60_Beaytiful_Daily",
      renming = "Shaw",
      renwu = "npc",
      role1 = 725000,
      role2 = 703102,
      role3 = 703202,
      sentence = "And the jade snuff bottle is the most unique and artistic of its kind.",
      next = {24}
    },
    [24] = {
      beijing = 1221,
      dialog = 2,
      idx = 8,
      music = "60_Beaytiful_Daily",
      renming = "Shaw",
      renwu = "npc",
      role1 = 725000,
      role2 = 703102,
      role3 = 703202,
      sentence = "It may not originate in Chinese, but over time it has taken on Chinese characteristics that have been preserved to this day.",
      next = {25}
    },
    [25] = {
      beijing = 1221,
      dialog = 2,
      idx = 8,
      music = "60_Beaytiful_Daily",
      renming = "Shaw",
      renwu = "npc",
      role1 = 725000,
      role2 = 703102,
      role3 = 703202,
      sentence = "My point is this:",
      next = {26}
    },
    [26] = {
      beijing = 1221,
      dialog = 3,
      music = "60_Beaytiful_Daily",
      renwu = "npc",
      role1 = 725000,
      role2 = 703102,
      role3 = 703201,
      sentence = "Shaw slightly straightened his back. A faint smile emerged in his eyes along with the reflection of the light.",
      next = {27}
    },
    [27] = {
      beijing = 1221,
      dialog = 2,
      idx = 8,
      music = "60_Beaytiful_Daily",
      renming = "Shaw",
      renwu = "npc",
      role1 = 725000,
      role2 = 703102,
      role3 = 703201,
      ruchang = 9,
      sentence = "When something falls out of use, the wisdom that went into creating it doesn't go away, and neither does its cultural significance.",
      next = {28}
    },
    [28] = {
      beijing = 1221,
      dialog = 3,
      music = "60_Beaytiful_Daily",
      renwu = "npc",
      sentence = "The student who asked the question seemed enlightened by that, but clearly wasn't fully convinced.",
      next = {29}
    },
    [29] = {
      beijing = 1221,
      dialog = 2,
      idx = 5,
      music = "60_Beaytiful_Daily",
      renming = "Student",
      renwu = "npc",
      sentence = "That may be true, but when something becomes outdated, it belongs in the past.",
      next = {30}
    },
    [30] = {
      beijing = 1221,
      dialog = 2,
      idx = 5,
      music = "60_Beaytiful_Daily",
      renming = "Student",
      renwu = "npc",
      sentence = "No matter how hard we try to preserve it, it won't change the fact that, culturally speaking, its job is done.",
      next = {31}
    },
    [31] = {
      beijing = 1221,
      dialog = 3,
      music = "60_Beaytiful_Daily",
      renwu = "npc",
      role1 = 726000,
      role2 = 712102,
      role3 = 712201,
      ruchang = -1,
      sentence = "Shaw put the KT board down and rubbed his chin thoughtfully for a moment.",
      next = {32}
    },
    [32] = {
      beijing = 1221,
      dialog = 2,
      idx = 8,
      music = "60_Beaytiful_Daily",
      renming = "Shaw",
      renwu = "npc",
      role1 = 726000,
      role2 = 712102,
      role3 = 712201,
      sentence = "Well, that brings us to another topic.",
      next = {33}
    },
    [33] = {
      beijing = 1221,
      dialog = 2,
      idx = 8,
      music = "60_Beaytiful_Daily",
      renming = "Shaw",
      renwu = "npc",
      role1 = 726000,
      role2 = 712102,
      role3 = 712201,
      sentence = "Strictly speaking, culture is more than just the objects that represent it.",
      next = {34}
    },
    [34] = {
      beijing = 1221,
      dialog = 2,
      idx = 8,
      music = "60_Beaytiful_Daily",
      renming = "Shaw",
      renwu = "npc",
      role1 = 726000,
      role2 = 712102,
      role3 = 712201,
      sentence = "In addition to tangible things that can be seen and touched, culture is also defined by the intangible, like thoughts and wisdom.",
      next = {35}
    },
    [35] = {
      beijing = 1221,
      dialog = 2,
      idx = 8,
      music = "60_Beaytiful_Daily",
      renming = "Shaw",
      renwu = "npc",
      role1 = 726000,
      role2 = 712102,
      role3 = 712201,
      sentence = "Any technology and device, no matter how popular they are, will eventually become obsolete.",
