      idx = 8,
      music = "60_Beaytiful_Daily",
      renming = "Shaw",
      renwu = "npc",
      role1 = 726000,
      role2 = 712102,
      role3 = 712201,
      sentence = "But the wisdom underlying them has always been there in our DNA—it's what makes us who we are.",
      next = {37}
    },
    [37] = {
