      dialog = 2,
      idx = 8,
      music = "60_Beaytiful_Daily",
      renming = "Shaw",
      renwu = "npc",
      role1 = 726000,
      role2 = 712102,
      role3 = 712201,
      ruchang = 9,
      sentence = "And that wisdom will never die—it will endure for eternity.",
      next = {38}
    },
    [38] = {
