      music = "60_Beaytiful_Daily",
      renwu = "npc",
      role1 = 725000,
      role2 = 703102,
      role3 = 703201,
      ruchang = -1,
      sentence = "He shifted his stance casually, a glint tucked away behind his eyes.",
      next = {39}
    },
    [39] = {
