      music = "60_Beaytiful_Daily",
      renming = "Shaw",
      renwu = "npc",
      role1 = 725000,
      role2 = 703102,
      role3 = 703201,
      sentence = "But its language and customs have made their way into Western culture and will stay there forever. The spirit of the Code of HammurAbbie will never fade with time.",
